-- Time tracker: full database setup for Cloudflare D1 (generated by demo/export-schema.mjs).
CREATE TABLE IF NOT EXISTS clients (
  id            TEXT PRIMARY KEY,
  name          TEXT NOT NULL UNIQUE,
  rate_cents    INTEGER NOT NULL DEFAULT 0,
  hours_cap     REAL,
  contact_name  TEXT NOT NULL DEFAULT '',
  contact_email TEXT NOT NULL DEFAULT '',
  paypal_email  TEXT NOT NULL DEFAULT '',
  currency      TEXT NOT NULL DEFAULT 'USD',
  archived      INTEGER NOT NULL DEFAULT 0,
  created_by    TEXT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now'))
, billing_model TEXT NOT NULL DEFAULT 'hourly'
  CHECK (billing_model IN ('hourly','milestone_weekly','monthly_retainer')), weekly_rate_cents INTEGER, monthly_retainer_cents INTEGER, week_start_day INTEGER NOT NULL DEFAULT 1
  CHECK (week_start_day >= 0 AND week_start_day <= 6), auto_send_report INTEGER NOT NULL DEFAULT 0, color TEXT
  CHECK (color IS NULL OR (length(color) = 7 AND substr(color, 1, 1) = '#' AND substr(color, 2) NOT GLOB '*[^0-9a-fA-F]*')), slug TEXT, paused INTEGER NOT NULL DEFAULT 0, paused_at TEXT, paused_by TEXT);
CREATE TABLE IF NOT EXISTS users (
  id            TEXT PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE,
  display_name  TEXT NOT NULL DEFAULT '',
  password_hash TEXT NOT NULL,
  password_salt TEXT NOT NULL,
  pbkdf2_iters  INTEGER NOT NULL DEFAULT 210000,
  role          TEXT NOT NULL DEFAULT 'employee'
                CHECK (role IN ('admin','employee','client')),
  client_id     TEXT REFERENCES clients(id) ON DELETE CASCADE,
  email_verified     INTEGER NOT NULL DEFAULT 0,
  email_verify_token TEXT,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now')), active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)), cost_rate_cents INTEGER NOT NULL DEFAULT 0,
  CHECK (
    (role = 'client'   AND client_id IS NOT NULL) OR
    (role IN ('admin','employee') AND client_id IS NULL)
  )
);
CREATE TABLE IF NOT EXISTS sessions (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at  TEXT NOT NULL,
  last_used_at TEXT
);
CREATE TABLE IF NOT EXISTS login_attempts (
  id         TEXT PRIMARY KEY,
  email      TEXT NOT NULL DEFAULT '',
  ip         TEXT NOT NULL DEFAULT '',
  success    INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS timesheets (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id)   ON DELETE CASCADE,
  client_id    TEXT NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,
  week_start   TEXT NOT NULL,
  status       TEXT NOT NULL DEFAULT 'open'
               CHECK (status IN ('open','submitted','approved','rejected')),
  approved_by  TEXT REFERENCES users(id) ON DELETE SET NULL,
  approved_at  TEXT,
  submitted_at TEXT,
  created_at   TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at   TEXT NOT NULL DEFAULT (datetime('now')), reject_reason TEXT,
  UNIQUE (user_id, client_id, week_start)
);
CREATE TABLE IF NOT EXISTS time_entries (
  id              TEXT PRIMARY KEY,
  user_id         TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  client_id       TEXT NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,
  project_task    TEXT NOT NULL DEFAULT '',
  entry_date      TEXT NOT NULL,
  hours           REAL NOT NULL CHECK (hours >= 0),
  rate_cents      INTEGER NOT NULL DEFAULT 0,
  is_billable     INTEGER NOT NULL DEFAULT 1,
  notes           TEXT NOT NULL DEFAULT '',
  approval_status TEXT NOT NULL DEFAULT 'open'
                  CHECK (approval_status IN ('open','submitted','approved','rejected')),
  approved_by     TEXT REFERENCES users(id) ON DELETE SET NULL,
  approved_at     TEXT,
  locked          INTEGER NOT NULL DEFAULT 0,
  invoice_id      TEXT REFERENCES invoices(id) ON DELETE SET NULL,
  timesheet_id    TEXT REFERENCES timesheets(id) ON DELETE SET NULL,
  created_at      TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at      TEXT NOT NULL DEFAULT (datetime('now'))
, entry_type TEXT NOT NULL DEFAULT 'work'
  CHECK (entry_type IN ('work', 'break', 'time_off', 'sick', 'holiday')), project_id TEXT REFERENCES projects(id) ON DELETE SET NULL, source TEXT
  CHECK (source IS NULL OR source IN ('timer','manual','import')), entered_by TEXT REFERENCES users(id), department_id TEXT REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS entry_edit_override (
  entry_id   TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS entry_deletions (
  id           TEXT PRIMARY KEY,
  entry_id     TEXT NOT NULL,
  deleted_by   TEXT NOT NULL,
  reason       TEXT NOT NULL DEFAULT '',
  was_approved INTEGER NOT NULL DEFAULT 0,
  snapshot     TEXT NOT NULL,
  created_at   TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS invoice_payments (
  id             TEXT PRIMARY KEY,
  invoice_id     TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  amount_cents   INTEGER NOT NULL CHECK (amount_cents > 0),
  payment_method TEXT NOT NULL DEFAULT '',
  reference      TEXT NOT NULL DEFAULT '',
  paid_at        TEXT NOT NULL DEFAULT (datetime('now')),
  created_at     TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS invoice_line_items (
  id            TEXT PRIMARY KEY,
  invoice_id    TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,
  time_entry_id TEXT REFERENCES time_entries(id) ON DELETE SET NULL,
  description   TEXT NOT NULL DEFAULT '',
  hours         REAL NOT NULL DEFAULT 0,
  rate_cents    INTEGER NOT NULL DEFAULT 0,
  amount_cents  INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS invoice_counters (
  year     INTEGER PRIMARY KEY,
  next_seq INTEGER NOT NULL DEFAULT 1
);
CREATE TABLE IF NOT EXISTS feedback (
  id          TEXT PRIMARY KEY,
  user_id     TEXT REFERENCES users(id) ON DELETE SET NULL,
  page        TEXT NOT NULL DEFAULT '',
  message     TEXT NOT NULL,
  status      TEXT NOT NULL DEFAULT 'open'
              CHECK (status IN ('open','done')),
  resolved_by TEXT REFERENCES users(id) ON DELETE SET NULL,
  resolved_at TEXT,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS member_client_weights (
  user_id                        TEXT NOT NULL REFERENCES users(id)   ON DELETE CASCADE,
  client_id                      TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  logged_hours_per_allotment_hour REAL NOT NULL DEFAULT 1
                                 CHECK (logged_hours_per_allotment_hour > 0),
  created_at                     TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at                     TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (user_id, client_id)
);
CREATE TABLE IF NOT EXISTS active_timers (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  client_id     TEXT NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,
  project_task  TEXT NOT NULL DEFAULT '',
  notes         TEXT NOT NULL DEFAULT '',
  started_at    TEXT NOT NULL
, department_id TEXT REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS notifications (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type        TEXT NOT NULL DEFAULT 'info',
  message     TEXT NOT NULL DEFAULT '',
  read        INTEGER NOT NULL DEFAULT 0 CHECK (read IN (0, 1)),
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS entry_edits (
  id          TEXT PRIMARY KEY,
  entry_id    TEXT NOT NULL REFERENCES time_entries(id) ON DELETE CASCADE,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  field_name  TEXT NOT NULL,
  old_value   TEXT,
  new_value   TEXT,
  reason      TEXT NOT NULL DEFAULT '',
  created_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS "invoices" (
  id             TEXT PRIMARY KEY,
  client_id      TEXT NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,
  created_by     TEXT REFERENCES users(id) ON DELETE SET NULL,
  invoice_number TEXT NOT NULL UNIQUE,
  period_start   TEXT NOT NULL,
  period_end     TEXT NOT NULL,
  status         TEXT NOT NULL DEFAULT 'draft'
                 CHECK (status IN ('draft','sent','paid','void','partially_paid')),
  currency       TEXT NOT NULL DEFAULT 'USD',
  total_hours    REAL NOT NULL DEFAULT 0,
  subtotal_cents INTEGER NOT NULL DEFAULT 0,
  total_cents    INTEGER NOT NULL DEFAULT 0,
  notes          TEXT NOT NULL DEFAULT '',
  due_date       TEXT,
  paid_at        TEXT,
  paid_amount_cents INTEGER NOT NULL DEFAULT 0,
  sent_at        TEXT,
  sent_to        TEXT NOT NULL DEFAULT '',
  created_at     TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS budget_alerts_sent (
  id          TEXT PRIMARY KEY,
  client_id   TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  week_start  TEXT NOT NULL,
  threshold   TEXT NOT NULL CHECK (threshold IN ('warning_80', 'exceeded_100', 'under_target_friday')),
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE(client_id, week_start, threshold)
);
CREATE TABLE IF NOT EXISTS client_updates (
  id            TEXT PRIMARY KEY,
  client_id     TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  week_start    TEXT NOT NULL,
  week_label    TEXT NOT NULL DEFAULT '',
  team_member   TEXT NOT NULL DEFAULT '',
  goals         TEXT NOT NULL DEFAULT '',
  achievements  TEXT NOT NULL DEFAULT '',
  department    TEXT NOT NULL DEFAULT '',
  status        TEXT NOT NULL DEFAULT '',
  is_internal   INTEGER NOT NULL DEFAULT 0,
  sort_order    INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS client_north_stars (
  id            TEXT PRIMARY KEY,
  client_id     TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  statement     TEXT NOT NULL DEFAULT '',
  updated_at    TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE(client_id)
);
CREATE TABLE IF NOT EXISTS projects (
  id          TEXT PRIMARY KEY,
  client_id   TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  name        TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  archived    INTEGER NOT NULL DEFAULT 0,
  created_by  TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at  TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE(client_id, name)
);
CREATE TABLE IF NOT EXISTS staff_roles (
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role       TEXT NOT NULL CHECK (role IN ('manager')),
  granted_by TEXT,
  granted_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (user_id, role)
);
CREATE TABLE IF NOT EXISTS client_assignments (
  user_id     TEXT NOT NULL REFERENCES users(id)   ON DELETE CASCADE,
  client_id   TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  assigned_by TEXT,
  assigned_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (user_id, client_id)
);
CREATE TABLE IF NOT EXISTS client_work_requests (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id)   ON DELETE CASCADE,
  client_id     TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  status        TEXT NOT NULL DEFAULT 'pending'
                CHECK (status IN ('pending','approved','denied')),
  note          TEXT NOT NULL DEFAULT '',
  requested_at  TEXT NOT NULL DEFAULT (datetime('now')),
  decided_by    TEXT,
  decided_at    TEXT,
  decision_note TEXT
);
CREATE TABLE IF NOT EXISTS app_settings (
  key        TEXT PRIMARY KEY,
  value      TEXT NOT NULL,
  updated_by TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS member_weights (
  user_id    TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  weight     REAL NOT NULL DEFAULT 1 CHECK (weight > 0),
  updated_by TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS user_weekly_budgets (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  week_start    TEXT,
  budget_hours  REAL NOT NULL CHECK (budget_hours > 0),
  set_by        TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS hour_budget_grants (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  week_start    TEXT NOT NULL,
  extra_hours   REAL NOT NULL CHECK (extra_hours > 0),
  request_id    TEXT,
  granted_by    TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS hour_budget_requests (
  id             TEXT PRIMARY KEY,
  user_id        TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  week_start     TEXT NOT NULL,
  hours          REAL NOT NULL CHECK (hours > 0),
  reason         TEXT NOT NULL DEFAULT '',
  status         TEXT NOT NULL DEFAULT 'pending'
                 CHECK (status IN ('pending','approved','denied')),
  granted_hours  REAL,
  decided_by     TEXT REFERENCES users(id) ON DELETE SET NULL,
  decided_at     TEXT,
  decision_note  TEXT,
  created_at     TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS hour_budget_alerts_sent (
  id          TEXT PRIMARY KEY,
  user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  week_start  TEXT NOT NULL,
  threshold   TEXT NOT NULL CHECK (threshold IN ('warning_80','limit_100')),
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE(user_id, week_start, threshold)
);
CREATE TABLE IF NOT EXISTS goals_sync_runs (
  id                    TEXT PRIMARY KEY,
  started_at            TEXT NOT NULL,
  finished_at           TEXT NOT NULL,
  created_count         INTEGER NOT NULL DEFAULT 0,
  updated_count         INTEGER NOT NULL DEFAULT 0,
  skipped_count         INTEGER NOT NULL DEFAULT 0,
  north_stars_updated   INTEGER NOT NULL DEFAULT 0,
  north_stars_skipped   INTEGER NOT NULL DEFAULT 0,
  unmapped_clients      TEXT NOT NULL DEFAULT '[]',
  partial               INTEGER NOT NULL DEFAULT 0,
  status                TEXT NOT NULL DEFAULT 'ok'
                        CHECK (status IN ('ok','partial'))
);
CREATE TABLE IF NOT EXISTS departments (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL UNIQUE,
  sort_order  INTEGER NOT NULL DEFAULT 0,
  hidden      INTEGER NOT NULL DEFAULT 0,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at  TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS client_billing (
  client_id           TEXT PRIMARY KEY REFERENCES clients(id) ON DELETE CASCADE,
  billing_model       TEXT
                      CHECK (billing_model IS NULL OR billing_model IN ('fixed_project','profit_share')),
  fixed_amount_cents  INTEGER,
  fixed_start         TEXT,
  fixed_end           TEXT,
  profit_pct          REAL,
  profit_base         TEXT,
  updated_by          TEXT REFERENCES users(id) ON DELETE SET NULL,
  updated_at          TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS invoice_voids (
  id               TEXT PRIMARY KEY,
  invoice_id       TEXT NOT NULL,
  invoice_number   TEXT NOT NULL DEFAULT '',
  client_id        TEXT,
  voided_by        TEXT REFERENCES users(id) ON DELETE SET NULL,
  voided_by_email  TEXT NOT NULL DEFAULT '',
  reason           TEXT NOT NULL DEFAULT '',
  hours_released   REAL NOT NULL DEFAULT 0,
  entries_released INTEGER NOT NULL DEFAULT 0,
  amount_released_cents INTEGER NOT NULL DEFAULT 0,
  snapshot         TEXT NOT NULL DEFAULT '{}',
  created_at       TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS lock_runs (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  through_date      TEXT    NOT NULL,
  entries_locked    INTEGER NOT NULL DEFAULT 0,
  timesheets_locked INTEGER NOT NULL DEFAULT 0,
  source            TEXT    NOT NULL,
  ran_at            TEXT    NOT NULL DEFAULT (datetime('now')),
  ran_by            TEXT
);
CREATE TABLE IF NOT EXISTS client_project_milestones (
  id            TEXT PRIMARY KEY,
  client_id     TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE,
  label         TEXT NOT NULL DEFAULT '',
  amount_cents  INTEGER NOT NULL CHECK (amount_cents >= 0),
  release_date  TEXT NOT NULL,
  released      INTEGER NOT NULL DEFAULT 0 CHECK (released IN (0,1)),
  landed_date   TEXT,
  created_by    TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_users_client ON users(client_id);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_expires ON sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_login_attempts_email ON login_attempts(email, created_at);
CREATE INDEX IF NOT EXISTS idx_login_attempts_ip    ON login_attempts(ip, created_at);
CREATE INDEX IF NOT EXISTS idx_timesheets_user   ON timesheets(user_id);
CREATE INDEX IF NOT EXISTS idx_timesheets_client ON timesheets(client_id);
CREATE INDEX IF NOT EXISTS idx_timesheets_week   ON timesheets(week_start);
CREATE INDEX IF NOT EXISTS idx_timesheets_status ON timesheets(status);
CREATE INDEX IF NOT EXISTS idx_entries_user ON time_entries(user_id);
CREATE INDEX IF NOT EXISTS idx_entries_client ON time_entries(client_id);
CREATE INDEX IF NOT EXISTS idx_entries_date ON time_entries(entry_date);
CREATE INDEX IF NOT EXISTS idx_entries_invoice ON time_entries(invoice_id);
CREATE INDEX IF NOT EXISTS idx_entries_status ON time_entries(approval_status);
CREATE INDEX IF NOT EXISTS idx_entries_timesheet ON time_entries(timesheet_id);
CREATE INDEX IF NOT EXISTS idx_entry_deletions_entry ON entry_deletions(entry_id);
CREATE INDEX IF NOT EXISTS idx_invoice_payments_invoice ON invoice_payments(invoice_id);
CREATE INDEX IF NOT EXISTS idx_lineitems_invoice ON invoice_line_items(invoice_id);
CREATE INDEX IF NOT EXISTS idx_feedback_status ON feedback(status, created_at);
CREATE INDEX IF NOT EXISTS idx_feedback_user ON feedback(user_id);
CREATE INDEX IF NOT EXISTS idx_mcw_client ON member_client_weights(client_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_active_timers_user ON active_timers(user_id);
CREATE INDEX IF NOT EXISTS idx_notifications_user_read ON notifications(user_id, read);
CREATE INDEX IF NOT EXISTS idx_notifications_created ON notifications(created_at);
CREATE INDEX IF NOT EXISTS idx_entry_edits_entry ON entry_edits(entry_id);
CREATE INDEX IF NOT EXISTS idx_entry_edits_created ON entry_edits(created_at);
CREATE INDEX IF NOT EXISTS idx_invoices_client ON invoices(client_id);
CREATE INDEX IF NOT EXISTS idx_budget_alerts_client_week ON budget_alerts_sent(client_id, week_start);
CREATE INDEX IF NOT EXISTS idx_client_updates_client ON client_updates(client_id);
CREATE INDEX IF NOT EXISTS idx_client_updates_week   ON client_updates(week_start);
CREATE INDEX IF NOT EXISTS idx_client_updates_combo  ON client_updates(client_id, week_start);
CREATE INDEX IF NOT EXISTS idx_projects_client ON projects(client_id, archived);
CREATE INDEX IF NOT EXISTS idx_time_entries_project ON time_entries(project_id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_clients_slug ON clients(slug);
CREATE INDEX IF NOT EXISTS idx_client_assignments_client ON client_assignments(client_id);
CREATE INDEX IF NOT EXISTS idx_work_requests_user ON client_work_requests(user_id, status);
CREATE INDEX IF NOT EXISTS idx_work_requests_status ON client_work_requests(status, requested_at);
CREATE UNIQUE INDEX IF NOT EXISTS idx_work_requests_pending
  ON client_work_requests(user_id, client_id) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS idx_entries_entered_by ON time_entries(entered_by);
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_weekly_budgets_week
  ON user_weekly_budgets(user_id, week_start) WHERE week_start IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_user_weekly_budgets_standing
  ON user_weekly_budgets(user_id) WHERE week_start IS NULL;
CREATE INDEX IF NOT EXISTS idx_user_weekly_budgets_user ON user_weekly_budgets(user_id);
CREATE INDEX IF NOT EXISTS idx_hour_budget_grants_user_week
  ON hour_budget_grants(user_id, week_start);
CREATE INDEX IF NOT EXISTS idx_hour_budget_requests_week
  ON hour_budget_requests(week_start, status);
CREATE UNIQUE INDEX IF NOT EXISTS idx_hour_budget_requests_pending
  ON hour_budget_requests(user_id, week_start) WHERE status = 'pending';
CREATE INDEX IF NOT EXISTS idx_hour_budget_alerts_user_week
  ON hour_budget_alerts_sent(user_id, week_start);
CREATE INDEX IF NOT EXISTS idx_goals_sync_runs_started ON goals_sync_runs(started_at);
CREATE INDEX IF NOT EXISTS idx_departments_sort ON departments(sort_order, name);
CREATE INDEX IF NOT EXISTS idx_entries_department ON time_entries(department_id);
CREATE INDEX IF NOT EXISTS idx_invoice_voids_invoice ON invoice_voids(invoice_id);
CREATE INDEX IF NOT EXISTS idx_invoice_voids_created ON invoice_voids(created_at);
CREATE INDEX IF NOT EXISTS idx_lock_runs_ran ON lock_runs(ran_at);
CREATE INDEX IF NOT EXISTS idx_client_project_milestones_client
  ON client_project_milestones(client_id, release_date);
CREATE INDEX IF NOT EXISTS idx_client_project_milestones_release
  ON client_project_milestones(release_date);
CREATE TRIGGER IF NOT EXISTS trg_timesheets_approved_no_regress
BEFORE UPDATE ON timesheets
FOR EACH ROW WHEN OLD.status = 'approved' AND NEW.status <> 'approved'
BEGIN
  SELECT RAISE(ABORT, 'timesheet is approved and immutable');
END;
CREATE TRIGGER IF NOT EXISTS trg_time_entries_locked_no_delete
BEFORE DELETE ON time_entries
FOR EACH ROW WHEN OLD.locked = 1
  AND NOT (OLD.invoice_id IS NULL AND EXISTS (SELECT 1 FROM entry_edit_override o WHERE o.entry_id = OLD.id))
BEGIN
  SELECT RAISE(ABORT, 'time_entry is approved+locked and immutable');
END;
CREATE TRIGGER IF NOT EXISTS trg_time_entries_locked_no_update
BEFORE UPDATE ON time_entries
FOR EACH ROW WHEN OLD.locked = 1
  AND NOT (OLD.invoice_id IS NULL AND EXISTS (SELECT 1 FROM entry_edit_override o WHERE o.entry_id = OLD.id))
  AND (
     NEW.hours           <> OLD.hours
  OR NEW.rate_cents       <> OLD.rate_cents
  OR NEW.entry_date       <> OLD.entry_date
  OR NEW.client_id        <> OLD.client_id
  OR NEW.user_id          <> OLD.user_id
  OR NEW.project_task     <> OLD.project_task
  OR NEW.is_billable      <> OLD.is_billable
  OR NEW.notes            <> OLD.notes
  OR NEW.approval_status  <> OLD.approval_status
  OR NEW.locked           <> OLD.locked
  OR NEW.timesheet_id IS NOT OLD.timesheet_id
  OR (OLD.invoice_id IS NOT NULL AND NEW.invoice_id IS NOT OLD.invoice_id
      AND NOT EXISTS (SELECT 1 FROM invoice_voids v WHERE v.invoice_id = OLD.invoice_id))
  )
BEGIN
  SELECT RAISE(ABORT, 'time_entry is approved+locked and immutable');
END;
